-- BookingBase HR Phase 1 - V9 Terminated Employees Sync (2026)
-- Adds 38 employees who left/terminated during 2026 into hr_employees and related tables
-- Total workforce becomes 338 ACTIVE + 38 INACTIVE = 376 employees

-- 1. Ensure Catalog rows

-- 2. Upsert 38 Terminated Employees into hr_employees

-- 3. Upsert Employment, Identity, Insurance, Contacts, and Movements for 38 Terminated Employees

-- 8. Restore active employees C720 (Châu Văn Hậu) and C722 (Lê Hoàng Tâm) who were assigned reuse codes in T5-26/T8-26
UPDATE hr_employees SET full_name = 'Châu Văn Hậu', employment_status = 'ACTIVE', status_effective_date = '2026-05-01', updated_at = NOW(6) WHERE employee_code = 'C720';
UPDATE hr_employee_employment SET termination_date = NULL, updated_at = NOW(6) WHERE employee_id IN (SELECT id FROM hr_employees WHERE employee_code = 'C720');
UPDATE hr_employee_insurance SET status = 'ACTIVE', updated_at = NOW(6) WHERE employee_id IN (SELECT id FROM hr_employees WHERE employee_code = 'C720');

UPDATE hr_employees SET full_name = 'Lê Hoàng Tâm', employment_status = 'ACTIVE', status_effective_date = '2026-05-01', updated_at = NOW(6) WHERE employee_code = 'C722';
UPDATE hr_employee_employment SET termination_date = NULL, updated_at = NOW(6) WHERE employee_id IN (SELECT id FROM hr_employees WHERE employee_code = 'C722');
UPDATE hr_employee_insurance SET status = 'ACTIVE', updated_at = NOW(6) WHERE employee_id IN (SELECT id FROM hr_employees WHERE employee_code = 'C722');
